INSERT INTO character_knowledge_records
(namespace,topic,summary,source_url,source_title,fetched_at,last_verified_at,canon_status,confidence,language,game_version,content_hash)
VALUES
('secondary','Sylus — Right-eye Aether Core: desire perception','Sylus has an Aether Core in his RIGHT EYE. This is confirmed directly in Long-Awaited Revelry 02-06: when the Main Character asks whether his Aether Core is in his eye, Sylus confirms it. He explains its specific ability: it helps him see what people want most and exposes desires they refuse to admit, even to themselves. The effect can intrude as intense impressions or visions in another person’s mind (the MC experiences chaotic noises and visions after looking into his eye). This is not the same as unrestricted telepathy: the game establishes perception of a person’s strongest/hidden desires, not automatic access to every passing thought, memory, or fact. Do not claim he can read all minds or memories. The Core is distinct from his Evol, which is Energy Manipulation. His right eye may glow red when his power is activated. Treat the desire-perception ability as established game canon; keep any broader claims about the Core’s origin, full mechanics, or limits uncertain unless a story source confirms them.','https://loveanddeepspace.wiki.gg/wiki/Long-Awaited_Revelry_02-06','Long-Awaited Revelry 02-06: Agreement — in-game story transcript',now(),now(),'secondary',0.99,'en','2026-11',md5('Sylus has an Aether Core in his RIGHT EYE. This is confirmed directly in Long-Awaited Revelry 02-06: when the Main Character asks whether his Aether Core is in his eye, Sylus confirms it. He explains its specific ability: it helps him see what people want most and exposes desires they refuse to admit, even to themselves. The effect can intrude as intense impressions or visions in another person’s mind (the MC experiences chaotic noises and visions after looking into his eye). This is not the same as unrestricted telepathy: the game establishes perception of a person’s strongest/hidden desires, not automatic access to every passing thought, memory, or fact. Do not claim he can read all minds or memories. The Core is distinct from his Evol, which is Energy Manipulation. His right eye may glow red when his power is activated. Treat the desire-perception ability as established game canon; keep any broader claims about the Core’s origin, full mechanics, or limits uncertain unless a story source confirms them.')),
('secondary','Aether Cores — distinction from Protocores and Evols','Aether Cores are exceptionally powerful and rare energy-related cores, treated in the story as surpassing ordinary Protocores. Sylus’s Aether Core is associated with his right eye; the Main Character’s is associated with her heart. The story also discusses the structure of a complete Aether Core, including an energy core, energy crystals formed through gravitational concentration, and an outer Aether Barrier that contains and stabilizes its energy. Do not assume every Aether Core has identical placement or abilities: the story notes more than one exists, and special variants such as the Spatium Core can affect space. Do not conflate an Aether Core with an Evol (a person’s ability) or assume every Protocore is an Aether Core.','https://loveanddeepspace.wiki.gg/wiki/Spacepedia/Note','Spacepedia — Aether Core notes',now(),now(),'secondary',0.97,'en','2026-11',md5('Aether Cores are exceptionally powerful and rare energy-related cores, treated in the story as surpassing ordinary Protocores. Sylus’s Aether Core is associated with his right eye; the Main Character’s is associated with her heart. The story also discusses the structure of a complete Aether Core, including an energy core, energy crystals formed through gravitational concentration, and an outer Aether Barrier that contains and stabilizes its energy. Do not assume every Aether Core has identical placement or abilities: the story notes more than one exists, and special variants such as the Spatium Core can affect space. Do not conflate an Aether Core with an Evol (a person’s ability) or assume every Protocore is an Aether Core.'))
